from django.forms import (
    Form,
    CharField,
    MultiValueField,
    MultiWidget,
)

class MF(MultiValueField):
    widget = MultiWidget
    def __init__(self):
        fields = [
            CharField(required=False),
            CharField(required=True),
        ]
        widget = self.widget(widgets=[
            f.widget
            for f in fields
        ], attrs={})
        super(MF, self).__init__(
            fields=fields,
            widget=widget,
            require_all_fields=False,
            required=False,
        )
    def compress(self, value):
        return []

class F(Form):
    mf = MF()

# Test 1: Both empty - should be invalid because mf_1 is required
f1 = F({
    'mf_0': '',
    'mf_1': '',
})
print(f'Test 1 (both empty): is_valid={f1.is_valid()}, errors={f1.errors}')

# Test 2: First has value, second is empty - should be invalid
f2 = F({
    'mf_0': 'xxx',
    'mf_1': '',
})
print(f'Test 2 (first has value): is_valid={f2.is_valid()}, errors={f2.errors}')

# Test 3: First is empty, second has value - should be valid
f3 = F({
    'mf_0': '',
    'mf_1': 'yyy',
})
print(f'Test 3 (second has value): is_valid={f3.is_valid()}, errors={f3.errors}')

# Test 4: Both have values - should be valid
f4 = F({
    'mf_0': 'xxx',
    'mf_1': 'yyy',
})
print(f'Test 4 (both have values): is_valid={f4.is_valid()}, errors={f4.errors}')
"

